import java.io.*;import java.security.*;import java.util.*;import com.android.apksig.ApkVerifier;
class VerifyApkToken61 {public static void main(String[]a)throws Exception{var r=new ApkVerifier.Builder(new File(a[0])).build().verify();if(!r.isVerified()||!r.isVerifiedUsingV1Scheme()||!r.isVerifiedUsingV2Scheme())throw new AssertionError("APK signatures invalid "+r.getErrors());var sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(r.getSignerCertificates().get(0).getEncoded()));if(!sha.equals("35867bcb9b79522df091687a6b2784fa7859dd68121ecb5a452a745735d39aa9"))throw new AssertionError("Original33 signer differs");System.out.println("PASS: APK v1/v2 signatures/content digests verified; signer matches Teste33: "+sha);System.out.println("Warnings: "+r.getWarnings());}}
